mapper.select:
SELECT u.*
FROM user u
JOIN block b ON b.blockee_id = u.id 
WHERE b.blocker_id = #{userId}
ORDER BY b.created_at DESC;

SELECT EXISTS(
    SELECT 1
    FROM block
    WHERE blocker_id = #{blockerId}
        AND blockee_id = #{blockeeId}
)

mapper.delete:
DELETE
FROM block
WHERE blocker_id = #{blockerId}
  AND blockee_id = #{blockeeId}
